def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    opp_c = 0
    opp_d = 0
    my_d = 0
    unprov = 0
    provoked = 0
    dc = 0
    trans_d = 0
    after_d = 0
    prev_my = 'C'

    for i, (me, op) in enumerate(history):
        if op == 'C':
            opp_c += 1
        else:
            opp_d += 1

        if me == 'D':
            my_d += 1

        if me == 'C' and op == 'D':
            if prev_my == 'D':
                provoked += 1
            else:
                unprov += 1

        if me == 'D' and op == 'C':
            dc += 1

        if i < n - 1 and me == 'D':
            trans_d += 1
            if history[i + 1][1] == 'C':
                after_d += 1

        prev_my = me

    last_me, last_op = history[-1]

    w = min(12, n)
    recent_opp_c = 0
    recent_opp_d = 0
    for i in range(n - w, n):
        op = history[i][1]
        if op == 'C':
            recent_opp_c += 1
        else:
            recent_opp_d += 1

    if opp_c == 0:
        return 'D'

    if recent_opp_c == 0:
        if provoked >= unprov and (opp_c * 2 >= n or unprov <= 2):
            return 'C'
        return 'D'

    if unprov >= 4 and unprov * 3 >= n:
        return 'D'

    if unprov >= 3 and recent_opp_d >= w - 1:
        return 'D'

    if opp_d * 3 >= n * 2 and recent_opp_d * 2 >= w and unprov >= 2:
        return 'D'

    if opp_d == 0 and n >= 8:
        return 'D'

    if last_op == 'D':
        if last_me == 'D':
            if opp_c * 3 >= n * 2 or recent_opp_c * 2 >= w or unprov <= 2:
                return 'C'
            return 'D'

        if n >= 2 and history[-2][0] == 'D':
            if opp_c * 2 >= n or recent_opp_c * 2 >= w:
                return 'C'

        if unprov <= 2 and recent_opp_c * 3 >= w * 2:
            return 'D'

        return 'D'

    if last_op == 'C':
        if last_me == 'D':
            if opp_d == 0:
                return 'D'

            if dc >= 2 and opp_d <= 2 and unprov <= 2 and opp_c * 3 >= n * 2:
                return 'D'

            if trans_d >= 2 and after_d * 3 >= trans_d * 2 and dc >= 1 and opp_c * 3 >= n * 2:
                return 'D'

            return 'C'

        if my_d >= 1 and dc >= 2 and opp_d <= max(2, my_d) and opp_c * 3 >= n * 2:
            return 'D'

        if trans_d >= 3 and after_d * 3 >= trans_d * 2 and opp_c * 3 >= n * 2:
            return 'D'

        return 'C'

    return 'C'
